var n=`0547-machboos`;var o=`world-0547`;var t=`AE`;var a=`western-asia`;var r=4;var s=86;var g={en:`Machboos`,ua:`Мачбус`};var d={en:`A traditional dish from United Arab Emirates, centered on chicken thigh, yellow onion, tomato, basmati rice. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Об'єднані Арабські Емірати. Основні складники: куряче стегно, жовта цибуля, помідор, рис басматі. Домашній варіант із кількостями продуктів за етапами приготування.`};var l=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 11 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 11 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:11,i:[[`chicken-thigh`,820,`g`],[`yellow-onion`,210,`g`],[`sunflower-oil`,55,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 42 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 42 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:42,i:[[`tomato`,380,`g`],[`ground-cardamom`,5,`g`],[`ground-cinnamon`,4,`g`],[`ground-cloves`,3,`g`],[`chicken-stock`,1050,`ml`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 29 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 29 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:29,i:[[`basmati-rice`,480,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`raisin`,75,`g`],[`almond`,60,`g`]]}];var m={slug:n,id:o,country:`AE`,region:a,servings:4,minutes:86,title:g,text:d,steps:l};export{t as country,m as default,o as id,s as minutes,a as region,r as servings,n as slug,l as steps,d as text,g as title};